-- Focus: Heart Failure, Cardiogenic Shock, Valvular Emergencies
-- Sources: Tintinalli 9e Ch 47-49, Step-Up to EM, Roberts & Hedges 7e

DO $$
DECLARE
    tid UUID;
BEGIN
    SELECT id INTO tid FROM topics WHERE slug = 'em-cardiac-emergencies' LIMIT 1;
